let imageHistory=[],imageHistoryAt=-1,imageHistoryBook=null,restoringImageHistory=false;
function resetImageHistory(){imageHistory=[];imageHistoryAt=-1;imageHistoryBook=book}
function rememberImageEdit(){
 if(playing||restoringImageHistory)return;
 if(imageHistoryBook!==book)resetImageHistory();
 const value=JSON.stringify(frames);
 if(imageHistory[imageHistoryAt]?.value!==value){
  imageHistory.splice(imageHistoryAt+1);
  imageHistory.push({value,current,selected});
  if(imageHistory.length>100)imageHistory.shift();
  imageHistoryAt=imageHistory.length-1;
 }
}
function restoreImageEdit(delta){
 const next=imageHistoryAt+delta;if(playing||next<0||next>=imageHistory.length)return;
 imageHistoryAt=next;const state=imageHistory[next];frames=JSON.parse(state.value);
 current=Math.min(state.current,frames.length-1);selected=state.selected;
 restoringImageHistory=true;render();restoringImageHistory=false;
}
function mirrorImage(direction){const p=piece();if(!p)return;p.flipX=direction;render()}
function message(s){$('status').textContent=s;$('status').classList.remove('hidden');clearTimeout(message.t);message.t=setTimeout(()=>$('status').classList.add('hidden'),2400)}
