 return new Promise((resolve,reject)=>{
  const tx=db.transaction('videos','readonly'),store=tx.objectStore('videos');
  if(id){const req=store.get(id);req.onsuccess=()=>{const v=req.result||null;db.close();resolve(v)};req.onerror=()=>{db.close();reject(req.error)}}
  else{const active=store.get('activeVideoId');active.onsuccess=()=>{if(!active.result){db.close();resolve(null);return}const req=store.get(active.result);req.onsuccess=()=>{const v=req.result||null;db.close();resolve(v)};req.onerror=()=>{db.close();reject(req.error)}};active.onerror=()=>{db.close();reject(active.error)}}
 });
