   if(confirm('Encontramos um projeto salvo neste iPad/navegador ('+BOOKS[draft.book]?.title+' - '+when+'). Deseja continuar de onde parou?')){
    if(!await restoreAutoDraft(draft)){message('O rascunho automático não pôde ser recuperado. Abra seu arquivo de projeto.');}
   }else{await clearAutoDraft()}
