(()=>{
const audio=document.getElementById('audio'),indicator=document.getElementById('voiceProgress'),wave=document.getElementById('voiceWave'),seek=document.getElementById('voiceSeek');
const heights=[6,12,17,9,15,19,11,7,18,13,8,16,19,10,14,7,17,12,19,9,15,6,13,18,8,16,11,19,9,14,7,17,12,6];
heights.forEach((height,i)=>{const bar=document.createElement('i');bar.style.setProperty('--h',height+'px');bar.style.setProperty('--delay',((i*37)%700)+'ms');wave.appendChild(bar)});
const update=()=>{const duration=audio.duration;seek.disabled=!(Number.isFinite(duration)&&duration>0);seek.value=seek.disabled?0:Math.round(audio.currentTime/duration*100)};
audio.addEventListener('timeupdate',update);audio.addEventListener('loadedmetadata',update);audio.addEventListener('durationchange',update);
audio.addEventListener('play',()=>indicator.classList.add('playing'));
for(const event of ['pause','ended','emptied'])audio.addEventListener(event,()=>{indicator.classList.remove('playing');update()});
seek.addEventListener('input',()=>{if(Number.isFinite(audio.duration)&&audio.duration>0)audio.currentTime=audio.duration*Number(seek.value)/100});
const recordButton=document.querySelector('#voiceActions button[aria-label="Gravar"]');
const stopButton=document.querySelector('#voiceActions button[aria-label="Parar"]');
const deleteButton=document.querySelector('#voiceActions button[aria-label="Apagar"]');
recordButton?.addEventListener('click',()=>{setTimeout(()=>{if(recordButton.classList.contains('recording'))indicator.classList.add('recording')},500)});
stopButton?.addEventListener('click',()=>indicator.classList.remove('recording'));
deleteButton?.addEventListener('click',()=>{indicator.classList.remove('recording','playing');seek.value=0;seek.disabled=true});
// Observe the actual recording button state, including when the recorder stops automatically.
if(window.MutationObserver&&recordButton)new MutationObserver(()=>indicator.classList.toggle('recording',recordButton.classList.contains('recording'))).observe(recordButton,{attributes:true,attributeFilter:['class']});
})();


